package career.assistant.application.audit;
import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class SubmissionAttemptServiceTest {
 @Test void firstClaimSucceedsAndSecondIsRejected(){var repo=mock(SubmissionAttemptRepository.class);when(repo.findFirstByApplicationIdOrderByCreatedAtDesc(any())).thenReturn(Optional.empty());when(repo.findFirstBySourceFingerprintAndStateIn(any(),any())).thenReturn(Optional.empty());when(repo.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));var s=new SubmissionAttemptService(repo);assertEquals(SubmissionAttemptState.IN_PROGRESS,s.claim(UUID.randomUUID(),"user","ASHBY","posting","key","request").state());}
 @Test void blockingAttemptRejectsDuplicate(){var repo=mock(SubmissionAttemptRepository.class);var a=new SubmissionAttempt();a.setState(SubmissionAttemptState.CONFIRMED);when(repo.findFirstByApplicationIdOrderByCreatedAtDesc(any())).thenReturn(Optional.of(a));var s=new SubmissionAttemptService(repo);assertThrows(SubmissionAttemptService.SubmissionAttemptConflictException.class,()->s.claim(UUID.randomUUID(),"user","ASHBY","posting","key","request"));}
 @Test void dryRunDoesNotClaim(){var repo=mock(SubmissionAttemptRepository.class);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var s=new SubmissionAttemptService(repo);var d=s.recordDryRun(UUID.randomUUID(),"user","ASHBY","posting","dry","sensitive-token");assertEquals(SubmissionAttemptState.DRY_RUN,d.state());verify(repo).save(any());verify(repo,never()).saveAndFlush(any());}
 @Test void ownershipIsPassedToOwnedQuery(){var repo=mock(SubmissionAttemptRepository.class);when(repo.findByOwnerSubjectOrderByCreatedAtDesc("u1")).thenReturn(List.of());new SubmissionAttemptService(repo).listOwned("u1");verify(repo).findByOwnerSubjectOrderByCreatedAtDesc("u1");}
}
